changeSet.sql:
alter table kontakt add constraint kontakt_aktiv_ck check (aktiv = (inaktiv_seit is null));
alter table kontakt add constraint kontakt_zusammengefuehrt_ck
    check (zusammengefuehrt_in is null or not aktiv);
alter table kontakt add constraint kontakt_zusammengefuehrt_selbst_ck check (zusammengefuehrt_in <> id);
create index kontakt_liste_ix on kontakt (aktiv, name_normalisiert, vorname, id);
create index kontakt_zusammengefuehrt_in_ix on kontakt (zusammengefuehrt_in)
    where zusammengefuehrt_in is not null;

alter table import_zeile drop constraint import_zeile_ergebnis_ck;
alter table import_zeile add constraint import_zeile_ergebnis_ck
    check (ergebnis is null or ergebnis in ('NEU', 'GEAENDERT', 'UNVERAENDERT', 'DUBLETTE', 'FEHLER',
        'UEBERSPRUNGEN', 'INAKTIV'));

alter table zugriff_protokoll drop constraint zugriff_protokoll_aktion_ck;
alter table zugriff_protokoll add constraint zugriff_protokoll_aktion_ck
    check (aktion in ('ERFASSEN', 'ANZEIGEN', 'HERUNTERLADEN', 'AENDERN', 'BESTAETIGEN', 'VERWERFEN',
        'WIEDERHOLEN', 'EXPORTIEREN', 'VERWEIGERT', 'SPERRE_KONFLIKT', 'REGEL_AENDERN', 'WISSEN_ANZEIGEN',
        'WISSEN_ANNEHMEN', 'WISSEN_VERWERFEN', 'WISSEN_INGEST', 'WISSEN_LINT', 'KONTAKT_ZUSAMMENFUEHREN',
        'KONTAKT_INAKTIV', 'KONTAKT_AKTIV'));
